declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/_auth.php';$p=portal_require();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$m=max(1,min(10,(int)($_POST['mood']??0)));$a=max(0,min(10,(int)($_POST['anxiety']??0)));db()->prepare("INSERT INTO mood_logs(tenant_id,patient_id,mood_score,anxiety_score,triggers,thoughts,created_at)VALUES(:t,:p,:m,:a,:tr,:th,NOW())")->execute(['t'=>$p['tenant_id'],'p'=>$p['id'],'m'=>$m,'a'=>$a?:null,'tr'=>trim($_POST['triggers']??'')?:null,'th'=>trim($_POST['thoughts']??'')?:null]);flash('success','Registro salvo para conversar na próxima sessão.');redirect('portal/index.php');}layout('Diário de humor',function(){?><div class="page-head"><div><span class="eyebrow">Entre sessões</span><h1>Diário de humor</h1><p>Registre sua percepção; isso não substitui atendimento de urgência ou acompanhamento profissional.</p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><div class="form-row"><div class="field"><label>Humor (1 a 10)</label><input type="number" name="mood" min="1" max="10" required></div><div class="field"><label>Ansiedade (0 a 10)</label><input type="number" name="anxiety" min="0" max="10"></div></div><div class="field"><label>Gatilhos / contexto</label><textarea name="triggers"></textarea></div><div class="field"><label>Pensamentos automáticos / observações</label><textarea name="thoughts"></textarea></div><button class="button">Salvar registro</button></form><?php },['portal'=>true]);
